function dfs(g,start) {
  const seen=new Set(),out=[];
  function visit(v){
    if(seen.has(v))return;seen.add(v);out.push(v);
    for(const w of g[v]??[])visit(w);
  }visit(start);return out;
}

static void dfs(Map<String,List<String>> g,String v,
                Set<String> seen,List<String> out) {
  if(!seen.add(v))return;out.add(v);
  for(String 
w:g.getOrDefault(v,List.of()))dfs(g,w,seen,out);
}
